// Basic-OS Cloudflare Worker — 静态网站托管（内嵌版）
// 将更新后的 index.html 直接内嵌在 Worker 中，不再依赖 GitHub 获取首页
// 其他静态资源仍然从 GitHub raw 代理

const BUNDLED_INDEX_HTML_B64 = `

`;

// 将 base64 解码为原始 HTML 字符串
function getBundledIndexHtml() {
  return atob(BUNDLED_INDEX_HTML_B64.trim());
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // 检查是否为 index.html 请求（各个路径变体）
    const isIndexRequest =
      path === '/' ||
      path === '/index.html' ||
      path === '/Basic-OS/' ||
      path === '/Basic-OS/index.html';

    // 如果是 index.html 请求，直接返回内嵌的 HTML
    if (isIndexRequest) {
      return new Response(getBundledIndexHtml(), {
        headers: {
          'Content-Type': 'text/html; charset=utf-8',
          'Cache-Control': 'public, max-age=3600',
          'Access-Control-Allow-Origin': '*',
        },
      });
    }

    // 代理 v86 虚拟机资源（核心文件走 jsdelivr CDN，镜像走 copy.sh）
    if (path.startsWith('/v86/')) {
      const v86Path = path.substring('/v86'.length); // e.g. /libv86.js, /v86.wasm, /bios/seabios.bin, /images/linux4.iso
      
      // 镜像文件走 copy.sh（仍然可用）
      let v86Url;
      if (v86Path.startsWith('/images/')) {
        v86Url = 'https://copy.sh/v86' + v86Path;
      } else {
        // 核心文件走 jsdelivr CDN
        v86Url = 'https://cdn.jsdelivr.net/npm/v86@latest' + v86Path;
      }
      
      try {
        const v86Resp = await fetch(v86Url);
        if (!v86Resp.ok) return new Response('v86 resource not found', { status: 404 });
        const v86Ext = v86Path.substring(v86Path.lastIndexOf('.')).toLowerCase();
        const v86Mime = {
          '.js': 'application/javascript; charset=utf-8',
          '.wasm': 'application/wasm',
          '.bin': 'application/octet-stream',
          '.iso': 'application/octet-stream',
        }[v86Ext] || 'application/octet-stream';
        return new Response(v86Resp.body, {
          headers: {
            'Content-Type': v86Mime,
            'Cache-Control': 'public, max-age=86400',
            'Access-Control-Allow-Origin': '*',
          },
        });
      } catch (e) {
        return new Response('v86 proxy error: ' + e.message, { status: 503 });
      }
    }

    // 对于其他路径，去掉 /Basic-OS 前缀后从 GitHub 代理
    let proxyPath = path;

    if (proxyPath.startsWith('/Basic-OS')) {
      proxyPath = proxyPath.substring('/Basic-OS'.length) || '/';
    }

    if (proxyPath === '/') proxyPath = '/index.html';

    // 根据扩展名设置 MIME 类型
    const mimeTypes = {
      '.html': 'text/html; charset=utf-8',
      '.css': 'text/css; charset=utf-8',
      '.js': 'application/javascript; charset=utf-8',
      '.json': 'application/json; charset=utf-8',
      '.ttf': 'font/ttf',
      '.woff': 'font/woff',
      '.woff2': 'font/woff2',
      '.iso': 'application/octet-stream',
      '.sh': 'text/plain; charset=utf-8',
      '.md': 'text/plain; charset=utf-8',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.svg': 'image/svg+xml',
      '.ico': 'image/x-icon',
    };

    const ext = proxyPath.substring(proxyPath.lastIndexOf('.')).toLowerCase();
    const contentType = mimeTypes[ext] || 'application/octet-stream';

    try {
      // 从 GitHub raw 获取文件
      const githubUrl = 'https://raw.githubusercontent.com/HuHuBasic/Basic-OS/main' + proxyPath;
      const response = await fetch(githubUrl);

      if (!response.ok) {
        // 如果文件不存在，返回内嵌的 index.html（SPA 回退）
        if (proxyPath !== '/index.html') {
          return new Response(getBundledIndexHtml(), {
            headers: { 'Content-Type': 'text/html; charset=utf-8' },
          });
        }
        return new Response('Not Found', { status: 404 });
      }

      return new Response(response.body, {
        headers: {
          'Content-Type': contentType,
          'Cache-Control': 'public, max-age=3600',
          'Access-Control-Allow-Origin': '*',
        },
      });
    } catch (e) {
      return new Response('Service Unavailable: ' + e.message, { status: 503 });
    }
  },
};
